function tideMarker({ marks, level }) {
    for (let j = 0; j < marks.length; j++)
        if (marks[j] > level)
            return j;
    return -1;
}

function tideMarker({ marks, level }) {
    let left = 0, right = marks.length;
    while (left < right) {
        const middle = left + Math.floor((right - left) / 2);
        if (marks[middle] > level)
            right = middle;
        else
            left = middle + 1;
    }
    return left === marks.length ? -1 : left;
}
